"""
    Slugify a string for use in URLs. This mirrors ``nsot.util.slugify()``.

    :param s:
        String to slugify
    """
def slugify(s: Any) -> object {
    disallowed_chars = ['/'];
    replacement = '_';
    for char in disallowed_chars {
        s = s.replace(char, replacement);
    }
    return s;
}

"""Format web url."""
def format_web_url(url: Any) -> object {
    url = url.replace("localhost", "http://127.0.0.1");
    if not url.startswith("http://") {
        return ("http://" + url);
    }
    return url;
}

